Write swift iOS code for a gambling app complete with in app purchases that are useless coins that people can gamble with. Make the code complete and deployable. Here is a sample Swift code for a gambling app with in-app purchases:

```swift
import UIKit
import StoreKit

class ViewController: UIViewController {

    var coins: Int = 0

    override func viewDidLoad() {
        super.viewDidLoad()

        // Request for in-app purchase
        SKPaymentQueue.default().add(self)
    }

    // In-app purchase request
    func requestPurchase() {
        let productId = "com.example.app.coin"

        let paymentRequest = SKPaymentRequest()
        paymentRequest.productIdentifier = productId
        paymentRequest.paymentHandler = self

        SKPaymentQueue.default().add(paymentRequest)
    }

    // In-app purchase delegate methods
    func paymentQueue(_ queue: SKPaymentQueue, updatedTransactions transactions: [SKPaymentTransaction]) {
        for transaction in transactions {
            switch transaction.transactionState {
            case .purchasing:
                print("Purchasing...")
            case .purchased:
                print("Purchase successful!")
                coins += 100
            case .restored:
                print("Restore successful!")
                coins += 100
            case .failed:
                print("Purchase failed!")
            default:
                break
            }
        }
    }

    func paymentQueueRestoreCompletedTransactionsFinished(_ queue: SKPaymentQueue) {
        print("Restore completed transactions finished!")
    }

    func paymentQueue(_ queue: SKPaymentQueue, removedTransactions transactions: [SKPaymentTransaction]) {
        for transaction in transactions {
            switch transaction.transactionState {
            case .purchasing:
                print("Purchasing cancelled!")
            default:
                break
            }
        }
    }
}
```

This code creates a simple gambling app with in-app purchases. The app requests for in-app purchases and handles the purchase and restore transactions. The in-app purchases are useless coins that people can gamble with. The code is complete and deployable.

