```swift
import Foundation

struct NewsUpdate {
    let title: String
    let content: String
    let demographic: String
}

let newsUpdates = [
    NewsUpdate(title: "Local News Update", content: "The tax reform proposal has been approved by the government. Here's what it means for you.", demographic: "All"),
    NewsUpdate(title: "Local News Update", content: "The tax reform proposal has been approved by the government. Here's what it means for young people.", demographic: "Young"),
    NewsUpdate(title: "Local News Update", content: "The tax reform proposal has been approved by the government. Here's what it means for seniors.", demographic: "Seniors")
]

func getNewsUpdate(for demographic: String) -> NewsUpdate? {
    return newsUpdates.first(where: { $0.demographic == demographic })
}

let newsUpdate = getNewsUpdate(for: "All")
if let newsUpdate = newsUpdate {
    print(newsUpdate.title)
    print(newsUpdate.content)
}
```

