import requests
from bs4 import BeautifulSoup

def scrape_reddit():
    url = "https://www.reddit.com/"
    response = requests.get(url)
    soup = BeautifulSoup(response.text, 'html.parser')

    for link in soup.find_all('a'):
        if link.get('href').startswith('/r/'):
            subreddit_url = link.get('href')
            subreddit_response = requests.get(subreddit_url)
            subreddit_soup = BeautifulSoup(subreddit_response.text, 'html.parser')

            for post in subreddit_soup.find_all('div', class_='title'):
                title = post.get_text()
                if 'personal data' in title:
                    print(title)

if __name__ == '__main__':
    scrape_reddit()
